@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Noto+Sans+KR:wght@400;500;600;700;800&display=swap');
:root{--ink:#eef3ff;--muted:#91a0b8;--gold:#e5ba7b;--cyan:#83d8e6;--violet:#b69cff;--bg:#090d17;--panel:rgba(13,20,34,.78);--line:rgba(190,211,240,.12)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:Manrope,'Noto Sans KR',sans-serif}button{font:inherit;color:inherit;cursor:pointer}.game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#0b111c}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 49%,transparent 35%,rgba(5,8,15,.2) 76%,rgba(5,8,15,.76) 130%),linear-gradient(180deg,rgba(5,9,16,.47),transparent 25%,transparent 67%,rgba(5,8,14,.62)}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:82px;padding:0 5.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(220,230,250,.08);background:linear-gradient(180deg,rgba(5,9,17,.64),transparent)}.brand{display:flex;align-items:center;gap:12px;color:#f5f4f0;text-decoration:none;font-size:12px;font-weight:800;letter-spacing:2.7px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(229,186,123,.56);color:var(--gold);font-size:17px;transform:rotate(45deg)}.brand-mark:before{content:'';position:absolute;width:24px;height:24px;border:1px solid rgba(229,186,123,.24)}.brand small{display:block;color:#9eabc0;font:9px 'DM Mono',monospace;letter-spacing:1.9px;margin-top:3px}.top-center{font:10px 'DM Mono',monospace;letter-spacing:2px;color:#bac5d7}.top-center i,footer i{color:var(--gold);font-style:normal;padding:0 6px}.season-dot,.eyebrow i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 11px var(--gold);vertical-align:1px;margin-right:8px}.top-actions{display:flex;gap:9px}.icon-btn{width:34px;height:34px;border-radius:50%;background:rgba(13,21,34,.46);border:1px solid var(--line);font-size:14px;color:#c3cee0}.icon-btn:hover{border-color:var(--gold);color:var(--gold)}.screen{position:absolute;z-index:5;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(7,11,19,.32);backdrop-filter:blur(1px)}[hidden]{display:none!important}.welcome{justify-content:flex-start;background:linear-gradient(90deg,rgba(6,10,18,.91) 0%,rgba(7,12,21,.75) 34%,rgba(7,12,21,.08) 74%,rgba(7,12,21,.12) 100%)}.welcome-copy{width:min(560px,52vw);margin-left:11.2%;padding-top:45px}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:2.5px;color:#c1cada;text-transform:uppercase}.eyebrow i{margin-right:11px;width:5px;height:5px}.welcome h1,.modal-card h2{font-size:clamp(43px,5.3vw,74px);line-height:1.17;letter-spacing:-3.8px;margin:22px 0 15px;font-weight:700}.welcome h1 em,.modal-card h2 em{font-style:normal;color:var(--gold);font-weight:500}.welcome-copy>p{font-size:13px;color:#aab5c5;line-height:1.95;margin:0 0 29px}.class-pick>small{font:9px 'DM Mono',monospace;letter-spacing:1.8px;color:#8794a9}.class-options{display:flex;gap:11px;margin-top:11px}.class-option{width:198px;height:94px;text-align:left;position:relative;padding:14px 12px 12px 53px;border:1px solid rgba(170,192,218,.15);background:rgba(17,26,41,.63);transition:.2s}.class-option:hover,.class-option.selected{border-color:rgba(229,186,123,.7);background:rgba(32,32,41,.8)}.class-option.selected{box-shadow:inset 0 0 24px rgba(229,186,123,.06)}.class-symbol{position:absolute;left:14px;top:17px;color:var(--violet);font-size:25px}.storm-symbol{color:#8cdde9}.class-option b{display:block;font-size:12px;letter-spacing:.4px;margin:2px 0 5px}.class-option small{font-size:9px;color:#95a3b8;white-space:nowrap}.class-option>i{position:absolute;right:10px;top:8px;color:var(--gold);font:8px 'DM Mono',monospace;font-style:normal;opacity:0}.class-option.selected>i{opacity:1}.start-btn{display:flex;align-items:center;justify-content:space-between;margin-top:22px;padding:0 21px;width:250px;height:50px;color:#171820;background:var(--gold);border:0;font-size:12px;font-weight:800;letter-spacing:.7px;box-shadow:0 8px 26px rgba(229,186,123,.17);transition:.2s}.start-btn span{font-size:19px;font-weight:400}.start-btn:hover{background:#f2d39f;transform:translateY(-2px);box-shadow:0 12px 34px rgba(229,186,123,.3)}.saved-note{margin-top:11px;color:#718096;font:9px 'DM Mono',monospace;letter-spacing:.8px}.welcome-side{position:absolute;right:11%;bottom:21%;display:flex;align-items:center;gap:18px;width:246px}.seal{width:58px;height:58px;border:1px solid rgba(229,186,123,.55);border-radius:50%;display:grid;place-items:center;color:var(--gold);font-size:17px;position:relative;flex:none}.seal:before,.seal:after{content:'';position:absolute;border:1px solid rgba(229,186,123,.2);border-radius:50%;inset:5px}.seal:after{inset:-5px;border-style:dashed;opacity:.5}.seal span{position:absolute;top:68px;font:7px 'DM Mono',monospace;line-height:1.6;letter-spacing:2px;text-align:center;color:#8f9db0}.side-copy{padding-left:16px;border-left:1px solid rgba(229,186,123,.48)}.side-copy b{font-size:11px;display:block;margin-bottom:5px}.side-copy span{font-size:9px;color:#93a0b2;line-height:1.6;display:block}.corner-note{position:absolute;left:5.2%;bottom:35px;color:#79869a;font:8px 'DM Mono',monospace;letter-spacing:1.8px}.corner-note span{color:var(--gold);padding:0 8px}
.glass{background:linear-gradient(120deg,rgba(17,26,42,.83),rgba(12,19,32,.6));border:1px solid rgba(191,211,238,.15);box-shadow:0 10px 35px rgba(0,0,0,.2);backdrop-filter:blur(10px)}.hud{position:absolute;z-index:2;inset:104px 5.2% auto;display:flex;align-items:flex-start;gap:35px}.player-card{display:flex;align-items:center;padding:11px 15px 11px 11px;width:240px;height:68px}.avatar{width:43px;height:43px;border:1px solid rgba(182,156,255,.52);background:linear-gradient(145deg,#282445,#161d30);display:grid;place-items:center;position:relative;margin-right:11px}.avatar span{color:#c6a9ff;font-size:22px}.online-dot{position:absolute;width:6px;height:6px;border-radius:50%;background:#79dcb4;right:3px;bottom:3px;border:1px solid #14202d}.player-info{flex:1}.player-name{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#e2e8f3;display:flex;justify-content:space-between}.player-name span{color:var(--gold);border:1px solid rgba(229,186,123,.4);padding:1px 5px;margin-top:-3px}.level-line{display:flex;justify-content:space-between;margin-top:5px;font:8px 'DM Mono',monospace;color:#9ba9bd}.xp-track,.health-track,.energy-track,.quest-progress,.boss-track{height:3px;background:rgba(202,216,239,.13);overflow:hidden}.xp-track{margin-top:5px}.xp-track i,.health-track i,.energy-track i,.quest-progress i,.boss-track i{height:100%;display:block;width:0%;background:var(--gold);transition:width .2s}.health-block{width:210px;padding-top:5px}.bar-label{display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#bbc6d6;margin-bottom:7px}.bar-label b{color:#e2e7ef;font-weight:400}.health-track{height:5px}.health-track i{background:linear-gradient(90deg,#d86f78,#edaa9b);box-shadow:0 0 8px #d86f78}.energy-track{margin-top:5px;height:3px}.energy-track i{background:linear-gradient(90deg,#7f86e9,#ba9fff);box-shadow:0 0 8px #877ce0}.energy-caption{text-align:right;font:7px 'DM Mono',monospace;color:#9c99cf;letter-spacing:1px;margin-top:4px}.wave-card{margin-left:auto;padding:10px 16px;min-width:132px}.wave-card small{font:8px 'DM Mono',monospace;color:#9caabe;letter-spacing:1px}.wave-card>b{display:block;font-size:18px;line-height:1.3;margin:3px 0}.wave-card>b span{font-size:11px;color:#8390a3;font-weight:400}.wave-card>div{font-size:9px;color:var(--gold)}.quest{position:absolute;z-index:2;left:5.2%;top:190px;display:flex;align-items:center;padding:12px 15px;gap:12px;min-width:225px}.quest-icon{font-size:19px;color:var(--gold)}.quest small{font:8px 'DM Mono',monospace;color:#9caabe;letter-spacing:1px;display:block;margin-bottom:5px}.quest b{font-size:10px;font-weight:500}.quest b span{color:var(--gold);font:9px 'DM Mono',monospace;margin-left:10px}.quest-progress{margin-top:8px}.quest-progress i{background:var(--gold)}.toast{position:absolute;z-index:3;left:50%;top:24%;transform:translate(-50%,-10px);opacity:0;color:#e5d6bd;background:rgba(10,15,24,.75);border:1px solid rgba(229,186,123,.4);padding:9px 16px;font:9px 'DM Mono',monospace;letter-spacing:1.5px;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.boss-bar{position:absolute;z-index:3;top:81%;left:50%;width:min(390px,60vw);transform:translateX(-50%);text-align:center}.boss-name{font:9px 'DM Mono',monospace;letter-spacing:1.8px;color:#e7d8d6;margin-bottom:7px}.boss-name>span{color:#e69a9a}.boss-name i{font-style:normal;color:#e58b88;font-size:7px;border:1px solid rgba(229,139,136,.5);padding:2px 5px;margin-left:5px}.boss-track{height:5px;background:rgba(50,27,34,.9);border:1px solid rgba(214,126,126,.25)}.boss-track i{background:linear-gradient(90deg,#a74653,#ed7979)}.damage-flash{position:absolute;inset:0;pointer-events:none;z-index:2;background:rgba(222,66,79,0);transition:background .1s}.damage-flash.flash{background:rgba(222,66,79,.16)}
.controls-hint{position:absolute;z-index:2;left:50%;bottom:48px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;padding:8px 14px;background:rgba(7,11,18,.5);border:1px solid rgba(190,211,240,.12);color:#bac5d5;font:8px 'DM Mono',monospace;letter-spacing:.4px;white-space:nowrap}.controls-hint>i{width:2px;height:2px;border-radius:50%;background:var(--gold)}kbd{display:inline-grid;place-items:center;min-width:16px;height:17px;padding:0 4px;margin-right:2px;background:rgba(200,218,241,.1);border:1px solid rgba(200,218,241,.2);color:#e4e9f1;font:8px 'DM Mono',monospace}.skills{position:absolute;z-index:2;bottom:48px;right:5.2%;display:flex;gap:7px}.skill-chip{height:38px;min-width:80px;padding:4px 8px;display:flex;align-items:center;gap:7px;background:rgba(9,14,24,.76);border:1px solid rgba(190,211,240,.15);font-size:8px;color:#bbc5d5;position:relative;overflow:hidden}.skill-chip kbd{width:21px;height:23px;margin:0;border-color:rgba(182,156,255,.4);color:#d1beff}.skill-chip i{position:absolute;inset:auto 0 0;height:0%;background:rgba(131,119,204,.29);pointer-events:none}.skill-chip.cooldown{color:#667186}.skill-chip.cooldown kbd{opacity:.55}.dash-chip{min-width:85px}.dash-chip kbd{width:auto;padding:0 5px;font-size:7px}
.levelup,.pause-screen,.result-screen{background:rgba(5,9,16,.76);backdrop-filter:blur(7px)}.modal-card{width:min(530px,90vw);padding:39px 45px;background:linear-gradient(145deg,rgba(21,29,44,.98),rgba(11,17,29,.97));border:1px solid rgba(229,186,123,.31);box-shadow:0 25px 100px #000b;position:relative}.modal-card:before{content:'';position:absolute;left:-1px;top:26px;width:2px;height:65px;background:var(--gold);box-shadow:0 0 13px var(--gold)}.modal-card h2{font-size:41px;letter-spacing:-1.6px;margin:15px 0 6px}.modal-card>p{font-size:11px;color:#9daabd;margin:0 0 23px}.upgrade-list{display:grid;gap:9px}.upgrade-card{padding:12px 14px;background:rgba(183,199,225,.055);border:1px solid rgba(183,199,225,.14);display:flex;align-items:center;text-align:left;gap:13px;transition:.2s}.upgrade-card:hover{border-color:var(--gold);background:rgba(229,186,123,.09);transform:translateX(3px)}.upgrade-icon{width:37px;height:37px;display:grid;place-items:center;font-size:18px;color:var(--gold);border:1px solid rgba(229,186,123,.3)}.upgrade-card b{font-size:11px;display:block;margin-bottom:4px}.upgrade-card small{font-size:9px;color:#97a5b8}.small-modal{width:min(430px,90vw);text-align:center;padding:38px 43px}.small-modal:before{left:50%;top:-1px;width:65px;height:2px;transform:translateX(-50%)}.small-modal .eyebrow{justify-content:center}.small-modal h2{font-size:38px}.small-modal .start-btn{margin:22px auto 0;text-align:left}.result-icon{font-size:28px;color:var(--gold);margin-bottom:13px;text-shadow:0 0 20px #c79759}.result-stats{display:flex;justify-content:center;gap:36px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:14px 0}.result-stats small{display:block;color:#8290a4;font:8px 'DM Mono',monospace;letter-spacing:1px;margin-bottom:5px}.result-stats b{font-size:18px;font-weight:500}.mobile-controls{display:none}footer{position:absolute;z-index:2;left:5.2%;right:5.2%;bottom:15px;display:flex;justify-content:space-between;color:#69768a;font:7px 'DM Mono',monospace;letter-spacing:1px;pointer-events:none}.mobile-portrait{display:none}
@media(max-width:850px){.welcome-copy{margin-left:7%;width:57vw}.welcome-side{right:6%;bottom:15%;width:210px}.hud{inset:95px 4% auto;gap:15px}.player-card{width:210px}.health-block{width:170px}.controls-hint{left:4%;transform:none}.skills{right:4%}.quest{left:4%;top:175px}}
@media(max-width:600px){.game-shell{min-height:420px}.topbar{height:62px;padding:0 5%}.brand{font-size:10px;letter-spacing:2px}.brand-mark{width:29px;height:29px}.brand small{font-size:7px}.top-center{font-size:7px;letter-spacing:1px}.icon-btn{width:30px;height:30px}.welcome{align-items:flex-start;background:linear-gradient(90deg,rgba(6,10,18,.88),rgba(7,12,21,.56) 80%,rgba(7,12,21,.3));}.welcome-copy{margin:17vh 0 0 7%;width:86%;padding:0}.welcome h1{font-size:48px;letter-spacing:-2.5px;margin:16px 0 10px}.welcome-copy>p{font-size:11px;line-height:1.7;margin-bottom:18px}.welcome-side{display:none}.class-options{gap:7px}.class-option{width:calc(50% - 3px);height:83px;padding:12px 7px 8px 42px}.class-symbol{left:10px;top:14px;font-size:21px}.class-option b{font-size:10px}.class-option small{font-size:8px}.class-option>i{font-size:7px}.class-pick>small{font-size:8px}.start-btn{height:46px;width:100%;margin-top:16px}.saved-note{font-size:8px}.corner-note{left:7%;bottom:22px;font-size:7px}.hud{inset:74px 4% auto;gap:8px;flex-wrap:wrap}.player-card{height:57px;width:calc(55% - 4px);padding:7px}.avatar{width:37px;height:37px}.player-name{font-size:7px}.level-line{font-size:7px}.health-block{width:calc(45% - 4px);padding-top:4px}.bar-label{font-size:7px}.wave-card{display:none}.quest{top:147px;left:4%;min-width:190px;padding:8px 11px}.quest b{font-size:9px}.quest small{font-size:7px}.toast{top:29%;font-size:8px;white-space:nowrap}.boss-bar{top:auto;bottom:95px;width:80vw}.controls-hint{display:none!important}.skills{display:none!important}.mobile-controls{display:block;position:absolute;z-index:3;inset:auto 0 19px;height:144px;pointer-events:none}.joystick{position:absolute;left:6%;bottom:8px;width:106px;height:106px;border-radius:50%;background:rgba(14,22,36,.57);border:1px solid rgba(194,215,241,.23);pointer-events:auto;touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;width:42px;height:42px;border-radius:50%;transform:translate(-50%,-50%);background:rgba(176,193,221,.24);border:1px solid rgba(207,222,244,.32)}.mobile-actions{position:absolute;right:5%;bottom:10px;display:flex;align-items:flex-end;gap:8px;pointer-events:auto}.mobile-actions button{width:53px;height:53px;border:1px solid rgba(190,211,240,.3);background:rgba(12,18,31,.74);border-radius:50%;font-size:8px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:3px;touch-action:none}.mobile-actions button span{font:10px 'DM Mono',monospace;color:var(--gold)}.mobile-actions .awaken-btn{width:60px;height:60px;border-color:rgba(182,156,255,.48);box-shadow:0 0 18px rgba(142,120,222,.16)}.mobile-actions .attack-btn{width:67px;height:67px;background:rgba(129,43,59,.8);border-color:rgba(239,128,135,.54);font-weight:700;font-size:10px}.mobile-portrait{position:absolute;z-index:4;inset:62px 0 0;background:#0a101a;align-items:center;justify-content:center;padding:24px;text-align:center;color:#aeb8c9;font:11px 'DM Mono',monospace;line-height:1.8}footer{display:none}.result-stats{gap:26px}.modal-card{padding:32px 25px}.modal-card h2{font-size:35px}}
@media(max-width:370px){.welcome-copy{margin-top:14vh}.welcome h1{font-size:41px}.class-option small{font-size:7px}.top-center{display:none}.hud{inset:70px 3% auto}.joystick{width:93px;height:93px}.mobile-actions{gap:5px}.mobile-actions button{width:48px;height:48px}.mobile-actions .awaken-btn{width:54px;height:54px}.mobile-actions .attack-btn{width:61px;height:61px}}

(() => {
  const canvas = document.querySelector('#game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {hud:$('hud'),quest:$('quest'),welcome:$('welcome'),levelup:$('levelup'),pause:$('pauseScreen'),result:$('resultScreen'),controls:$('controlsHint'),skills:$('skills'),mobile:$('mobileControls'),toast:$('toast'),boss:$('bossBar')};
  const colors = {veil:'#bb9cff',storm:'#83d9e8'};
  let W=innerWidth,H=innerHeight,DPR=1,keys={},last=0,elapsed=0,toastTimer=0,selectedClass='veil',running=false,paused=false,levelScreen=false,gameOver=false;
  let p,enemies=[],particles=[],slashes=[],rays=[],decor=[],worldTime=0,spawnTimer=0,wave=0,kills=0,combo=0,comboTime=0,shake=0;
  let player={x:0,y:0,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,damage:25,speed:210,attackCd:0,skillCd:0,ultCd:0,invuln:0,dash:0,dashDir:{x:1,y:0},face:{x:1,y:0},rank:'E',upgrades:{}};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0);if(!player.x){player.x=W*.5;player.y=H*.65}decor=Array.from({length:Math.max(34,Math.round(W/20))},()=>({x:rand(0,W),y:rand(H*.47,H*.88),s:rand(.4,1.3),a:rand(.06,.3)}))}
  addEventListener('resize',resize);resize();
  function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
  function updateHud(){ $('level').textContent=`LV. ${String(player.level).padStart(2,'0')}`;$('xpText').textContent=`${player.xp} / ${xpNeed()} XP`;$('xpBar').style.width=`${Math.min(100,player.xp/xpNeed()*100)}%`;$('hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('hpBar').style.width=`${Math.max(0,player.hp/player.maxHp*100)}%`;$('energyBar').style.width=`${player.energy/player.maxEnergy*100}%`;$('rank').textContent=player.rank;$('killText').textContent=`${kills} / ${[5,7,1][Math.min(wave,2)]||5}`;$('questBar').style.width=`${Math.min(100,kills/([5,7,1][Math.min(wave,2)]||5)*100)}%`; $('waveText').innerHTML=`${String(Math.max(1,wave+1)).padStart(2,'0')} <span>/ 03</span>`; $('waveName').textContent=['잊힌 사원','달빛 숲','심연의 문'][Math.min(wave,2)]||'정화 완료';
    const boss=enemies.find(e=>e.boss);ui.boss.hidden=!boss;if(boss)$('bossHpBar').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;
    for(const [id,cd,max] of [['skillQ',player.skillCd,5],['skillE',player.ultCd,13]]){const el=$(id);el.classList.toggle('cooldown',cd>0);el.querySelector('i').style.height=`${cd>0?Math.max(0,100-cd/max*100):0}%`}
  }
  function xpNeed(){return 80+(player.level-1)*35}
  function startGame(){
    selectedClass=document.querySelector('.class-option.selected')?.dataset.class||'veil';
    player={x:W*.5,y:H*.66,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,damage:selectedClass==='storm'?29:25,speed:210,attackCd:0,skillCd:0,ultCd:0,invuln:0,dash:0,dashDir:{x:1,y:0},face:{x:1,y:0},rank:'E',upgrades:{}};
    enemies=[];particles=[];slashes=[];rays=[];kills=0;combo=0;wave=0;spawnTimer=.6;running=true;paused=false;levelScreen=false;gameOver=false;
    ui.welcome.hidden=true;ui.levelup.hidden=true;ui.pause.hidden=true;ui.result.hidden=true;ui.hud.hidden=false;ui.quest.hidden=false;ui.controls.hidden=false;ui.skills.hidden=false;ui.mobile.hidden=false;
    if(localStorage.getItem('riftBest'))$('savedNote').textContent=`최고 기록 · 레벨 ${localStorage.getItem('riftBest')} 계승자`;
    announce('첫 번째 균열이 열렸습니다');updateHud();
