(() => {
  const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');const $=id=>document.getElementById(id);
  const ui={hud:$('hud'),quest:$('quest'),welcome:$('welcome'),levelup:$('levelup'),pause:$('pauseScreen'),result:$('resultScreen'),controls:$('controlsHint'),skills:$('skills'),mobile:$('mobileControls'),toast:$('toast'),boss:$('bossBar')};
  const colors={veil:'#bb9cff',storm:'#83d9e8'};
  let W=innerWidth,H=innerHeight,DPR=1,keys={},last=0,elapsed=0,toastTimer=0,selectedClass='veil',running=false,paused=false,levelScreen=false,gameOver=false,transitioning=false;
  let p,enemies=[],particles=[],slashes=[],rays=[],decor=[],worldTime=0,spawnTimer=0,wave=0,kills=0,combo=0,comboTime=0,shake=0;
  let player={x:0,y:0,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,damage:25,speed:210,attackCd:0,skillCd:0,ultCd:0,invuln:0,dash:0,dashDir:{x:1,y:0},face:{x:1,y:0},rank:'E',upgrades:{}};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0);if(!player.x){player.x=W*.5;player.y=H*.65}decor=Array.from({length:Math.max(34,Math.round(W/20))},()=>({x:rand(0,W),y:rand(H*.47,H*.88),s:rand(.4,1.3),a:rand(.06,.3)}))}
  addEventListener('resize',resize);resize();
  function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
  function updateHud(){$('level').textContent=`LV. ${String(player.level).padStart(2,'0')}`;$('xpText').textContent=`${player.xp} / ${xpNeed()} XP`;$('xpBar').style.width=`${Math.min(100,player.xp/xpNeed()*100)}%`;$('hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('hpBar').style.width=`${Math.max(0,player.hp/player.maxHp*100)}%`;$('energyBar').style.width=`${player.energy/player.maxEnergy*100}%`;$('rank').textContent=player.rank;$('killText').textContent=`${kills} / ${[5,6,1][Math.min(wave,2)]||5}`;$('questBar').style.width=`${Math.min(100,kills/([5,6,1][Math.min(wave,2)]||5)*100)}%`;$('waveText').innerHTML=`${String(Math.max(1,wave+1)).padStart(2,'0')} <span>/ 03</span>`;$('waveName').textContent=['잊힌 사원','달빛 숲','심연의 문'][Math.min(wave,2)]||'정화 완료';const boss=enemies.find(e=>e.boss);ui.boss.hidden=!boss;if(boss)$('bossHpBar').style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`;for(const[id,cd,max]of[['skillQ',player.skillCd,5],['skillE',player.ultCd,13]]){const el=$(id);el.classList.toggle('cooldown',cd>0);el.querySelector('i').style.height=`${cd>0?Math.max(0,100-cd/max*100):0}%`}}
  function xpNeed(){return 80+(player.level-1)*35}
  function startGame(){selectedClass=document.querySelector('.class-option.selected')?.dataset.class||'veil';player={x:W*.5,y:H*.66,r:17,hp:100,maxHp:100,energy:100,maxEnergy:100,xp:0,level:1,damage:selectedClass==='storm'?29:25,speed:210,attackCd:0,skillCd:0,ultCd:0,invuln:0,dash:0,dashDir:{x:1,y:0},face:{x:1,y:0},rank:'E',upgrades:{}};enemies=[];particles=[];slashes=[];rays=[];kills=0;combo=0;wave=0;spawnTimer=.6;running=true;paused=false;levelScreen=false;gameOver=false;transitioning=false;ui.welcome.hidden=true;ui.levelup.hidden=true;ui.pause.hidden=true;ui.result.hidden=true;ui.hud.hidden=false;ui.quest.hidden=false;ui.controls.hidden=false;ui.skills.hidden=false;ui.mobile.hidden=false;if(localStorage.getItem('riftBest'))$('savedNote').textContent=`최고 기록 · 레벨 ${localStorage.getItem('riftBest')} 계승자`;announce('첫 번째 균열이 열렸습니다');updateHud()}
  function pauseGame(){if(!running||levelScreen||gameOver)return;paused=!paused;ui.pause.hidden=!paused}
  function endGame(won){if(gameOver)return;running=false;gameOver=true;ui.result.hidden=false;ui.controls.hidden=true;ui.skills.hidden=true;ui.mobile.hidden=true;ui.boss.hidden=true;$('resultIcon').textContent=won?'✦':'✧';$('resultEyebrow').innerHTML=`<i></i> ${won?'RIFT CLEARED':'RUN ENDED'}`;$('resultTitle').innerHTML=won?'균열이<br/><em>정화되었습니다.</em>':'아직 끝나지<br/><em>않았습니다.</em>';$('resultDescription').textContent=won?'당신의 힘은 한 단계 더 성장했습니다. 새로운 균열이 기다립니다.':'이번 도전에서 얻은 경험은 사라지지 않습니다. 다시 도전하세요.';$('resultKills').textContent=kills;$('resultLevel').textContent=player.level;$('resultRank').textContent=player.rank;const best=+localStorage.getItem('riftBest')||1;if(player.level>best)localStorage.setItem('riftBest',player.level)}
  let pendingUpgrades=[];
  function upgradeOptions(){const pool=[{icon:'⚔',name:'예리한 칼날',desc:'모든 공격 피해 +20%',apply:()=>player.damage*=1.2},{icon:'♥',name:'생명력 각성',desc:'최대 체력 +30 · 체력 회복',apply:()=>{player.maxHp+=30;player.hp=Math.min(player.maxHp,player.hp+45)}},{icon:'✧',name:'잔영의 축복',desc:'에너지 회복 속도 +40%',apply:()=>player.upgrades.energy=(player.upgrades.energy||0)+.4},{icon:'➤',name:'바람을 쫓아서',desc:'이동 속도 +12%',apply:()=>player.speed*=1.12},{icon:'◉',name:'긴 그림자',desc:'검술 범위 +25%',apply:()=>player.upgrades.range=(player.upgrades.range||0)+.25},{icon:'✦',name:'연속 각성',desc:'각성 피해 +35%',apply:()=>player.upgrades.ult=(player.upgrades.ult||0)+.35}];return[...pool].sort(()=>Math.random()-.5).slice(0,3)}
  function showLevelup(){levelScreen=true;paused=true;ui.levelup.hidden=false;pendingUpgrades=upgradeOptions();const list=$('upgradeList');list.innerHTML='';pendingUpgrades.forEach((u,i)=>{const b=document.createElement('button');b.className='upgrade-card';b.innerHTML=`<span class="upgrade-icon">${u.icon}</span><span><b>${u.name}</b><small>${u.desc}</small></span>`;b.onclick=()=>chooseUpgrade(i);list.appendChild(b)})}
  function chooseUpgrade(i){const u=pendingUpgrades[i];if(!u)return;u.apply();player.level++;player.xp-=xpNeed();player.hp=Math.min(player.maxHp,player.hp+22);player.energy=player.maxEnergy;levelScreen=false;ui.levelup.hidden=true;paused=false;announce(`${u.name} · 레벨 ${player.level} 달성`);updateHud();if(player.xp>=xpNeed())showLevelup()}
  function spawnEnemy(type='wraith'){const angle=rand(0,Math.PI*2),distFrom=rand(Math.min(W,H)*.35,Math.min(W,H)*.53),boss=type==='boss',hp=boss?560:(type==='brute'?135:75)*(1+wave*.3);enemies.push({x:clamp(player.x+Math.cos(angle)*distFrom,35,W-35),y:clamp(player.y+Math.sin(angle)*distFrom,100,H-80),r:boss?29:type==='brute'?22:16,hp,maxHp:hp,damage:boss?20:8+wave*2,speed:boss?52:type==='brute'?35:58+wave*4,boss,type,attack:rand(.3,1.2),hit:0,phase:rand(0,6),color:boss?'#e98a94':type==='brute'?'#d588ad':'#ae8bce'})}
